business=[]
for s in scope:
    if s['w2']!='UI/开':continue
    conditional=s['source']!='PRD'
    for k,(title,kind,steps,expected,basis) in enumerate(scenarios[s['seq']],1):
        awaiting=conditional or s['seq'] in ['3','4','15'] or (s['seq']=='55' and k==1)
        business.append({'id':f"W2-{int(s['seq']):02d}-{k}",'seq':s['seq'],'row':s['row'],'module':s['level2'],'priority':s['priority'],'title':title,'kind':kind,'precondition':('先完成PRD/入口评审；' if conditional else '')+'提供该业务页的批准设计与可切换前端状态样例；本地通用模板仅作对照','steps':steps,'expected':expected,'status':'待基线确认' if awaiting else '待业务页执行','basis':basis,'evidence':'无本业务页实测证据','owner':'待安排','result':'未执行'})
templates=[]
def t(id,title,steps,expected,status,actual,evidence,basis,issue=''):
    templates.append(dict(id=id,title=title,steps=steps,expected=expected,status=status,actual=actual,evidence=evidence,basis=basis,issue=issue,owner='待安排',result='待复测' if issue else ''))
